PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,locality TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','archived')),plan TEXT NOT NULL DEFAULT 'free' CHECK(plan IN ('free','standard','business')),plan_started_at INTEGER NOT NULL,plan_expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,org_id TEXT REFERENCES organizations(id),email TEXT NOT NULL COLLATE NOCASE UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('superadmin','admin','agent','member')),password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,password_version INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),password_version INTEGER NOT NULL,csrf_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS login_attempts(identifier TEXT PRIMARY KEY,count INTEGER NOT NULL,window_start INTEGER NOT NULL,blocked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,org_id TEXT,user_id TEXT,action TEXT NOT NULL,target TEXT,details TEXT,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_org ON audit_logs(org_id,created_at);
CREATE TABLE IF NOT EXISTS reset_requests(id TEXT PRIMARY KEY,org_id TEXT,user_id TEXT NOT NULL,reason TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL,handled_at INTEGER);
CREATE TABLE IF NOT EXISTS cycles(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,share_value INTEGER NOT NULL DEFAULT 500,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','closed')),start_at INTEGER NOT NULL,closed_at INTEGER,UNIQUE(org_id,name));
CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),code TEXT NOT NULL,name TEXT NOT NULL,phone TEXT DEFAULT '',locality TEXT DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,UNIQUE(org_id,code));
CREATE INDEX IF NOT EXISTS idx_member_org ON members(org_id);
CREATE TABLE IF NOT EXISTS meetings(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),cycle_id TEXT NOT NULL REFERENCES cycles(id),meeting_date TEXT NOT NULL,notes TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS savings(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),cycle_id TEXT NOT NULL REFERENCES cycles(id),member_id TEXT NOT NULL REFERENCES members(id),meeting_id TEXT REFERENCES meetings(id),shares INTEGER NOT NULL CHECK(shares>0),share_value INTEGER NOT NULL CHECK(share_value>0),amount INTEGER NOT NULL CHECK(amount>0),created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_savings_scope ON savings(org_id,cycle_id,member_id);
CREATE TABLE IF NOT EXISTS loans(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),cycle_id TEXT NOT NULL REFERENCES cycles(id),member_id TEXT NOT NULL REFERENCES members(id),principal INTEGER NOT NULL CHECK(principal>0),rate_percent REAL NOT NULL CHECK(rate_percent>=0 AND rate_percent<=100),interest_total INTEGER NOT NULL DEFAULT 0,term_days INTEGER NOT NULL DEFAULT 30,due_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS repayments(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),loan_id TEXT NOT NULL REFERENCES loans(id),amount INTEGER NOT NULL CHECK(amount>0),principal_amount INTEGER NOT NULL DEFAULT 0,interest_amount INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_repay_loan ON repayments(loan_id);
CREATE TABLE IF NOT EXISTS solidarity(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),cycle_id TEXT NOT NULL REFERENCES cycles(id),member_id TEXT REFERENCES members(id),kind TEXT NOT NULL CHECK(kind IN ('income','expense')),amount INTEGER NOT NULL CHECK(amount>0),notes TEXT DEFAULT '',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS expenses(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),cycle_id TEXT NOT NULL REFERENCES cycles(id),amount INTEGER NOT NULL CHECK(amount>0),description TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS distributions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES organizations(id),cycle_id TEXT NOT NULL UNIQUE REFERENCES cycles(id),profit INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS distribution_items(id TEXT PRIMARY KEY,distribution_id TEXT NOT NULL REFERENCES distributions(id),member_id TEXT NOT NULL REFERENCES members(id),savings INTEGER NOT NULL,profit_share INTEGER NOT NULL,total INTEGER NOT NULL);
